package io.github.samlinb.openbone.core;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import io.github.samlinb.openbone.application.*;
import io.github.samlinb.openbone.core.math.*;
import io.github.samlinb.openbone.core.model.*;
import io.github.samlinb.openbone.io.*;
import static io.github.samlinb.openbone.TestData.id;
import static org.junit.jupiter.api.Assertions.*;

class PathConstraintTest {
 static PathAttachment line(boolean constant){return new PathAttachment(id(11),"path",id(10),List.of(new Vec2(-10,0),new Vec2(0,0),new Vec2(100./3,0),new Vec2(200./3,0),new Vec2(100,0),new Vec2(110,0)),false,constant,List.of(200.,0.));}
 static DocumentSnapshot fixture(boolean constant,double mix){var path=line(constant);return new DocumentSnapshot(List.of(new Bone(id(1),"root",null,Transform.IDENTITY,0),new Bone(id(2),"arm",id(1),new Transform(-10,20,45,1,1),100),new Bone(id(3),"tip",id(2),new Transform(100,0,0,1,1),20),new Bone(id(4),"path-bone",id(1),Transform.IDENTITY,0)),List.of(new Slot(id(10),"path-slot",id(4),id(11))),List.of(path)).withConstraints(List.of(new PathConstraint(id(5),"follow",0,true,List.of(id(2)),id(10),PathConstraint.PositionMode.PERCENT,PathConstraint.SpacingMode.FIXED,PathConstraint.RotateMode.TANGENT,.25,20,0,mix,mix,mix)));}
 static void near(double a,double b){IkConstraintTest.near(a,b);}
 @ParameterizedTest @CsvSource({"true,0.0,-10,20,45","true,0.5,7.5,10,22.5","true,1,25,0,0","false,1,25,0,0"})
 void straightLineAnalyticPoseAndUnchangedSetup(boolean constant,double mix,double x,double y,double angle){var d=fixture(constant,mix);var w=d.evaluateWorld();var m=w.bones().get(id(2)).matrix();near(x,m.tx());near(y,m.ty());near(Math.cos(Math.toRadians(angle)),m.a());near(Math.sin(Math.toRadians(angle)),m.c());var child=w.bones().get(id(3));near(x+100*m.a(),child.origin().x());near(y+100*m.c(),child.origin().y());assertEquals(new Transform(-10,20,45,1,1),d.bone(id(2)).local());assertEquals(line(constant).vertices(),w.paths().get(id(11)));}
 @Test void openExtendsAlongEndpointHandlesAndUsesStoredLength(){var p=line(true);near(-20,PathConstraintSolver.position(p,p.vertices(),-20).point().x());near(120,PathConstraintSolver.position(p,p.vertices(),120).point().x());var non=line(false);near(12.5,PathConstraintSolver.position(non,non.vertices(),25).point().x());near(25,PathConstraintSolver.position(p,p.vertices(),25).point().x());}
 @Test void closedUsesPositiveModuloAndKeepsSeamPosition(){var p=new PathAttachment(id(11),"closed",id(10),List.of(new Vec2(-20,20),new Vec2(0,0),new Vec2(20,20)),true,true,List.of(100.));double length=PathConstraintSolver.pathLength(p,p.vertices());var start=PathConstraintSolver.position(p,p.vertices(),0).point();assertEquals(start,PathConstraintSolver.position(p,p.vertices(),length).point());var a=PathConstraintSolver.position(p,p.vertices(),-.25*length).point();var b=PathConstraintSolver.position(p,p.vertices(),.75*length).point();near(a.x(),b.x());near(a.y(),b.y());}
 @Test void zeroPathAndMirroredSlotAreDeterministic(){var d=fixture(true,1);var mirrored=ModelEdits.editBone(d,id(4),b->b.withLocal(new Transform(10,5,0,-2,1)));var m=mirrored.evaluateWorld().bones().get(id(2)).matrix();near(-40,m.tx());near(5,m.ty());near(-1,m.a());near(0,m.c());var zero=PathEdits.edit(d,id(11),p->p.withVertices(Collections.nCopies(6,new Vec2(3,4))));var w=zero.evaluateWorld();near(3,w.bones().get(id(2)).origin().x());near(4,w.bones().get(id(2)).origin().y());assertEquals(new PathConstraintSolver.Position(new Vec2(3,4),0),PathConstraintSolver.position((PathAttachment)zero.attachments().get(0),Collections.nCopies(6,new Vec2(3,4)),100));}
 @Test void spacingChainAndChainScaleHaveIndependentStraightExpectations(){for(var mode:PathConstraint.RotateMode.values()){var d=fixture(true,1);var c=(PathConstraint)d.constraints().get(0);d=d.withConstraints(List.of(c.withModes(PathConstraint.PositionMode.FIXED,PathConstraint.SpacingMode.FIXED,mode).withValue(0,0).withValue(1,40).withBones(List.of(id(2),id(3)))));var w=d.evaluateWorld();near(0,w.bones().get(id(2)).origin().x());near(mode==PathConstraint.RotateMode.CHAIN?100:40,w.bones().get(id(3)).origin().x());near(mode==PathConstraint.RotateMode.CHAIN_SCALE?.4:1,w.bones().get(id(2)).matrix().a());}}
 @Test void ownRoundtripWithoutConstraintRetainsUnusedOpenLength()throws Exception{var codec=new ProjectCodec();for(boolean speed:new boolean[]{false,true}){var d=fixture(speed,.5);assertEquals(d,codec.decode(codec.encode(d)));var standalone=d.withConstraints(List.of());assertEquals(standalone,codec.decode(codec.encode(standalone)));assertEquals(0.,((PathAttachment)d.attachments().get(0)).lengths().get(1));}}
 @Test void referencesDeletionUndoAndVertexHistory(){var d=fixture(true,1);var h=new ProjectDocument(d).history();h.select(Selection.of(id(11)));h.execute("vertex",Commands.model(v->PathEdits.vertex(v,id(11),2,new Vec2(40,60))));assertTrue(h.undo());assertEquals(d,h.state().model());h.execute("delete slot",Commands.model(v->ModelEdits.delete(v,id(10))));assertTrue(h.state().model().constraints().isEmpty());assertTrue(h.undo());assertEquals(d,h.state().model());var c=(PathConstraint)d.constraints().get(0);assertThrows(IllegalArgumentException.class,()->d.withConstraints(List.of(c.withTarget(id(2)))));assertThrows(IllegalArgumentException.class,()->d.withConstraints(List.of(c.withBones(List.of(id(4))))));assertEquals(id(4),EditorEdits.transformId(d,id(5)));}
 @Test void pathDoesNotEnterTexturedGeometryOrPicking(){var d=fixture(true,1);assertTrue(io.github.samlinb.openbone.viewport.VisibleGeometry.evaluate(d,d.evaluateWorld()).isEmpty());assertTrue(io.github.samlinb.openbone.viewport.Picker.region(d,new Vec2(25,0),new io.github.samlinb.openbone.viewport.ImageAssets()).isEmpty());}
 @ParameterizedTest @CsvSource({"FIXED,FIXED,TANGENT","PERCENT,PERCENT,CHAIN","PERCENT,LENGTH,CHAIN_SCALE","FIXED,PROPORTIONAL,TANGENT"})
 void runtimeRoundtripPreservesModesGeometryAndUnusedLength(String position,String spacing,String rotation)throws Exception{
  var d=fixture(true,.5);var c=(PathConstraint)d.constraints().get(0);d=d.withConstraints(List.of(c.withModes(PathConstraint.PositionMode.valueOf(position),PathConstraint.SpacingMode.valueOf(spacing),PathConstraint.RotateMode.valueOf(rotation)).withValue(1,spacing.equals("PERCENT")?.1:20)));var codec=new SkeletonJsonCodec();var bytes=codec.encode(d,Map.of(),"");var actual=codec.decode(bytes,java.nio.file.Path.of("D:/tmp"));var p=(PathConstraint)actual.constraints().get(0);assertEquals(c.position(),p.position());assertEquals(position,p.positionMode().name());assertEquals(spacing,p.spacingMode().name());assertEquals(rotation,p.rotateMode().name());assertEquals(line(true).vertices(),((PathAttachment)actual.attachments().get(0)).vertices());assertEquals(List.of(200.,0.),((PathAttachment)actual.attachments().get(0)).lengths());var expected=d.evaluateWorld().bones().get(id(2)).matrix();var arm=actual.bones().stream().filter(b->b.name().equals("arm")).findFirst().orElseThrow();assertEquals(expected,actual.evaluateWorld().bones().get(arm.id()).matrix());
 }
 @Test void unsupportedWeightedDeformModeAndRuntimeDegeneracyDoNotLoseTheProject()throws Exception{
  var d=fixture(true,.5);var codec=new SkeletonJsonCodec();var json=new com.fasterxml.jackson.databind.ObjectMapper();var tree=json.readTree(codec.encode(d,Map.of(),""));var attachment=(com.fasterxml.jackson.databind.node.ObjectNode)tree.path("skins").get(0).path("attachments").path("path-slot").path("path");attachment.putArray("vertices").add(1).add(0).add(0).add(0).add(1);final var weightedTree=tree;assertTrue(assertThrows(ProjectFormatException.class,()->codec.decode(json.writeValueAsBytes(weightedTree),java.nio.file.Path.of("D:/tmp"))).getMessage().contains("Weighted path"));
  tree=json.readTree(codec.encode(d,Map.of(),""));((com.fasterxml.jackson.databind.node.ObjectNode)tree.path("path").get(0)).put("positionMode","Percent");final var badMode=tree;assertTrue(assertThrows(ProjectFormatException.class,()->codec.decode(json.writeValueAsBytes(badMode),java.nio.file.Path.of("D:/tmp"))).getMessage().contains("positionMode"));
  var zero=PathEdits.edit(d,id(11),p->p.withVertices(Collections.nCopies(6,new Vec2(0,0))));assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(zero));assertEquals(zero,new ProjectCodec().decode(new ProjectCodec().encode(zero)));var animated=AnimationEdits.put(d,d.animations().get(0).id(),id(4),io.github.samlinb.openbone.core.animation.Channel.TRANSLATE,0,List.of(5.,0.));assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(animated));assertEquals(animated,new ProjectCodec().decode(new ProjectCodec().encode(animated)));
 }
}
